#!/usr/bin/env python3
"""PreToolUse(Edit|Write|NotebookEdit): generated files, lockfiles and secrets are never edited by hand (exit 2).

A generated file is one under the default generated paths, or any file whose first line is devkit's generated
marker (so a project that moves its generated directory is still covered)."""

import json
import re
import sys

RULES = [
    (r"(^|/)docs/generated/", "docs/generated/ is generated: change the source, then `uv run dev docs`."),
    (r"(^|/)docs/research/INDEX\.md$", "INDEX.md is generated from the notes: edit the note, then `uv run dev docs`."),
    (r"(^|/)uv\.lock$", "uv.lock is written by uv: `uv add` / `uv lock`."),
    (r"(^|/)\.env(\.[\w-]+)?$(?<!\.example)", "Secrets stay out of agent hands: the owner edits .env."),
    (r"(^|/)devkit/quota_cap$", "the quota cap is the owner's: `! uv run dev quota-cap <pct>`, never an agent."),
]
MARKER = "<!-- Generated by `uv run dev docs`."


def generated(path: str) -> bool:
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            return f.readline().startswith(MARKER)
    except OSError:
        return False


def main() -> int:
    try:
        data = json.load(sys.stdin)
    except json.JSONDecodeError:
        return 0
    if not isinstance(data, dict) or not isinstance(data.get("tool_input"), dict):
        return 0
    inp = data["tool_input"]
    path = inp.get("file_path") or inp.get("notebook_path") or ""
    if not isinstance(path, str):
        return 0
    for pattern, why in RULES:
        if re.search(pattern, path):
            print(f"Blocked by project rule: {why}", file=sys.stderr)
            return 2
    if generated(path):
        print(
            "Blocked by project rule: the file is generated: change its source, then `uv run dev docs`.",
            file=sys.stderr,
        )
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
